INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10601, 'តើសមីការខាងក្រោមមួយណាជា «សមីការអសនិទាន»?', NULL, '["\\(\\sqrt{2x - 1} = 5\\)", "\\(2x + \\sqrt{5} = 7\\)", "\\(\\dfrac{x}{\\sqrt{2}} = 3\\)", "\\(x^2 - \\sqrt{3}x + 2 = 0\\)"]', 0, NULL, 1, 'mcq', 'សមីការអសនិទានគឺជាសមីការដែលមានអញ្ញាត \(x\) ស្ថិតនៅក្រោមរ៉ាឌីកាល់។ ដូច្នេះ \(\sqrt{2x-1} = 5\) ជាសមីការអសនិទាន។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'easy', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10602, 'ដោះស្រាយសមីការអសនិទាន \(\sqrt{x - 3} = 4\) ក្នុងសំណុំចំនួនពិត៖', NULL, '["\\(x = 19\\)", "\\(x = 16\\)", "\\(x = 11\\)", "\\(x = 7\\)"]', 0, NULL, 1, 'mcq', 'លក្ខខណ្ឌ \(x - 3 \ge 0 \implies x \ge 3\)។ លើកជាការេ៖ \(x - 3 = 16 \implies x = 19\) (ផ្ទៀងផ្ទាត់)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'easy', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10603, 'ដោះស្រាយសមីការ \(\sqrt{2x + 1} = -5\) ក្នុងសំណុំចំនួនពិត \(\mathbb{R}\)៖', NULL, '["\\(x = 12\\)", "គ្មានឫសក្នុងសំណុំចំនួនពិត", "\\(x = 24\\)", "\\(x = -12\\)"]', 1, NULL, 1, 'mcq', 'ដោយសាររ៉ាឌីកាល់ការេនៃចំនួនពិតជានិច្ចកាលមិនអវិជ្ជមាន (\(\sqrt{2x+1} \ge 0\)) វាមិនអាចស្មើនឹងចំនួនអវិជ្ជមាន \(-5\) បានឡើយ។ ដូច្នេះសមីការគ្មានឫស។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'easy', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10604, 'ក្នុងសមីការ \(\sqrt{7 - x} = x - 1\) គេទទួលបានសមីការដឺក្រេទីពីរ \(x^2 - x - 6 = 0\) ដែលមានឫស \(x = 3\) និង \(x = -2\)។ តើតម្លៃណាជាឫសពិតនៃសមីការដើម?', NULL, '["\\(x = -2 \\text{ តែមួយគត់}\\)", "\\(\\text{គ្មានឫស}\\)", "\\(x = 3 \\text{ តែមួយគត់}\\)", "\\(x = 3 \\text{ និង } x = -2\\)"]', 2, NULL, 1, 'mcq', 'លក្ខខណ្ឌអង្គខាងស្តាំត្រូវមិនអវិជ្ជមាន៖ \(x - 1 \ge 0 \implies x \ge 1\)។ ដូច្នេះ \(x = 3 \ge 1\) ផ្ទៀងផ្ទាត់ ចំណែក \(x = -2 < 1\) ជាឫសក្រៅ (មិនយក)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'easy', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10605, 'តើដឺក្រេនៃសមីការ \(2x^4 - 3x^2 + x - 5 = 0\) ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(3\\)", "\\(4\\)", "\\(2\\)", "\\(5\\)"]', 1, NULL, 1, 'mcq', 'ដឺក្រេនៃសមីការគឺជាដឺក្រេខ្ពស់បំផុតនៃពហុធា ដែលស្មើនឹង 4 ហៅថាសមីការដឺក្រេទី 4។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'easy', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10606, 'ដោះស្រាយសមីការ \(x^3 - 27 = 0\) ក្នុងសំណុំចំនួនពិត \(\mathbb{R}\)៖', NULL, '["\\(x = -3\\)", "\\(x = \\pm 3\\)", "\\(x = 9\\)", "\\(x = 3\\)"]', 3, NULL, 1, 'mcq', '\(x^3 - 27 = 0 \iff (x - 3)(x^2 + 3x + 9) = 0\)។ ដោយ \(x^2 + 3x + 9 = 0\) មាន \(\Delta = 9 - 36 = -27 < 0\) នាំឱ្យឫសពិតតែមួយគត់គឺ \(x = 3\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'easy', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10607, 'តាមទ្រឹស្តីបទសំណល់ សំណល់នៃការចែកពហុធា \(f(x)\) នឹងទ្វេធា \(x - \alpha\) គឺ៖', NULL, '["\\(R = f(-\\alpha)\\)", "\\(R = -f(\\alpha)\\)", "\\(R = f(0)\\)", "\\(R = f(\\alpha)\\)"]', 3, NULL, 1, 'mcq', 'ទ្រឹស្តីបទសំណល់ចែងថា បើ \(R\) ជាសំណល់នៃការចែកពហុធា \(f(x)\) នឹង \(x - \alpha\) នោះ \(R = f(\alpha)\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'easy', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10608, 'រកសំណល់នៃការចែកពហុធា \(f(x) = x^3 + 2x - 5\) នឹង \(x - 1\)៖', NULL, '["\\(-5\\)", "\\(-2\\)", "\\(2\\)", "\\(0\\)"]', 1, NULL, 1, 'mcq', 'តាមទ្រឹស្តីបទសំណល់ \(R = f(1) = 1^3 + 2(1) - 5 = 1 + 2 - 5 = -2\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'easy', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10609, 'ទ្វេធា \(x - 2\) ជាកត្តានៃពហុធា \(f(x)\) លុះត្រាតែ៖', NULL, '["\\(f(2) = 0\\)", "\\(f(0) = 2\\)", "\\(f(2) = 2\\)", "\\(f(-2) = 0\\)"]', 0, NULL, 1, 'mcq', 'តាមទ្រឹស្តីបទកត្តា \(x - \alpha\) ជាកត្តានៃ \(f(x)\) លុះត្រាតែសំណល់ \(R = f(\alpha) = 0\) ដូច្នេះ \(f(2) = 0\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'easy', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10610, 'បន្ទះកាតុងរាងចតុកោណកែងមួយមានបណ្តោយ \(12\text{ cm}\) និងទទឹង \(8\text{ cm}\)។ គេកាត់ការេជ្រុង \(x\text{ cm}\) នៅគ្រប់កាច់ជ្រុងទាំងបួនរួចបត់ធ្វើជាប្រអប់គ្មានគម្រប។ រូបមន្តគណនាមាឌប្រអប់ \(V(x)\) គឺ៖', NULL, '["\\(V(x) = x(12 - x)(8 - x)\\)", "\\(V(x) = 4x(12 - 2x)(8 - 2x)\\)", "\\(V(x) = x(12 - 2x)(8 - 2x)\\)", "\\(V(x) = (12 - 2x)(8 - 2x)\\)"]', 2, NULL, 1, 'mcq', 'កម្ពស់ប្រអប់គឺ \(x\), បណ្តោយបាតគឺ \(12 - 2x\) និងទទឹងបាតគឺ \(8 - 2x\) ដូច្នេះមាឌ \(V = x(12-2x)(8-2x)\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'easy', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10611, 'ដោះស្រាយសមីការអសនិទាន \(\sqrt{2x - 1} = x - 2\)៖', NULL, '["\\(x = 1 \\text{ ឬ } x = 5\\)", "\\(x = 5\\)", "\\(x = 1\\)", "\\(x = 3\\)"]', 1, NULL, 2, 'mcq', 'លក្ខខណ្ឌ \(x - 2 \ge 0 \implies x \ge 2\)។ លើកជាការេ៖ \(2x - 1 = x^2 - 4x + 4 \iff x^2 - 6x + 5 = 0 \iff (x-1)(x-5) = 0\)។ ដោយ \(x \ge 2\) នាំឱ្យ \(x = 5\) (យក) ចំណែក \(x = 1\) (មិនយក)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'medium', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10612, 'ដោះស្រាយសមីការ \(\sqrt{3x + 1} = \sqrt{x + 9}\)៖', NULL, '["\\(x = 4\\)", "\\(x = 5\\)", "\\(x = 2\\)", "\\(x = 8\\)"]', 0, NULL, 2, 'mcq', 'លក្ខខណ្ឌ \(x \ge -1/3\)។ លើកជាការេ៖ \(3x + 1 = x + 9 \iff 2x = 8 \implies x = 4\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'medium', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10613, 'ដោះស្រាយសមីការ \(x - \sqrt{x} - 12 = 0\) ក្នុងសំណុំចំនួនពិត៖', NULL, '["\\(x = 16\\)", "\\(x = 9\\)", "\\(x = 16 \\text{ ឬ } x = 9\\)", "\\(x = 4\\)"]', 0, NULL, 2, 'mcq', 'តាង \(t = \sqrt{x} \ge 0\) នាំឱ្យ \(t^2 - t - 12 = 0 \iff (t-4)(t+3) = 0 \implies t = 4\) (ព្រោះ \(t \ge 0\)) \implies \(\sqrt{x} = 4 \implies x = 16\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'medium', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10614, 'ដោះស្រាយសមីការ \(\dfrac{8}{\sqrt{10-2x}} - \sqrt{10-2x} = 7\)៖', NULL, '["\\(x = \\dfrac{9}{2}\\)", "\\(x = 5\\)", "\\(x = 4\\)", "\\(x = \\dfrac{7}{2}\\)"]', 0, NULL, 2, 'mcq', 'លក្ខខណ្ឌ \(x < 5\)។ តាង \(t = \sqrt{10-2x} > 0\) នាំឱ្យ \(8 - t^2 = 7t \iff t^2 + 7t - 8 = 0 \implies t = 1\) (ព្រោះ \(t > 0\))។ គេបាន \(10 - 2x = 1 \implies 2x = 9 \implies x = 9/2\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'medium', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10615, 'ដោះស្រាយសមីការទ្វេការេ \(x^4 - 10x^2 + 9 = 0\) ក្នុងសំណុំចំនួនពិត៖', NULL, '["\\(x = \\pm 1, \\; \\pm 9\\)", "\\(x = 1, \\; 3\\)", "\\(x = \\pm 1, \\; \\pm 3\\)", "\\(x = \\pm 2, \\; \\pm 3\\)"]', 2, NULL, 2, 'mcq', 'តាង \(t = x^2 \ge 0\) នាំឱ្យ \(t^2 - 10t + 9 = 0 \iff (t-1)(t-9) = 0 \implies t = 1, 9\)។ ដូច្នេះ \(x^2 = 1 \implies x = \pm 1\) និង \(x^2 = 9 \implies x = \pm 3\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'medium', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10616, 'ដោះស្រាយសមីការ \(x^4 - 2x^2 - 8 = 0\) ក្នុងសំណុំចំនួនកុំផ្លិច \(\mathbb{C}\)៖', NULL, '["\\(x = \\pm\\sqrt{2}, \\; \\pm 2i\\)", "\\(x = \\pm 2, \\; \\pm\\sqrt{2}i\\)", "\\(x = \\pm 2, \\; \\pm 2i\\)", "\\(x = \\pm 4, \\; \\pm\\sqrt{2}i\\)"]', 1, NULL, 2, 'mcq', 'តាង \(t = x^2\) នាំឱ្យ \(t^2 - 2t - 8 = 0 \iff (t-4)(t+2) = 0 \implies t = 4\) ឬ \(t = -2\)។ បើ \(t = 4 \implies x = \pm 2\) ហើយបើ \(t = -2 \implies x = \pm\sqrt{2}i\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'medium', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10617, 'ដោះស្រាយសមីការដឺក្រេទីបី \(x^3 + 3x^2 - 4x - 12 = 0\) តាមវិធីផ្តុំតួ៖', NULL, '["\\(x = -3, \\; 0, \\; 2\\)", "\\(x = -3, \\; \\pm 2\\)", "\\(x = \\pm 3, \\; 2\\)", "\\(x = 3, \\; \\pm 2\\)"]', 1, NULL, 2, 'mcq', '\(x^2(x+3) - 4(x+3) = 0 \iff (x+3)(x^2-4) = 0 \iff (x+3)(x-2)(x+2) = 0 \implies x = -3, \; 2, \; -2\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'medium', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10618, 'រកសំណល់នៃការចែកពហុធា \(P(x) = 4x^3 - 2x^2 - 9\) នឹង \(2x - 1\)៖', NULL, '["\\(-9\\)", "\\(-7\\)", "\\(0\\)", "\\(9\\)"]', 0, NULL, 2, 'mcq', 'តាមទ្រឹស្តីបទសំណល់ \(R = P(1/2) = 4(1/8) - 2(1/4) - 9 = 1/2 - 1/2 - 9 = -9\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'medium', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10619, 'រកតម្លៃ \(a\) ដើម្បីឱ្យពហុធា \(P(x) = x^4 - 2x + a\) ចែកដាច់នឹង \(x + 2\)៖', NULL, '["\\(a = 20\\)", "\\(a = -12\\)", "\\(a = -20\\)", "\\(a = 12\\)"]', 2, NULL, 2, 'mcq', 'ពហុធាចែកដាច់នឹង \(x + 2 \iff P(-2) = 0 \iff (-2)^4 - 2(-2) + a = 0 \iff 16 + 4 + a = 0 \implies a = -20\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'medium', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10620, 'រកតម្លៃ \(p\) ដែលនាំឱ្យពហុធា \(x^3 - 3x^2 + 4x + p\) ចែកដាច់នឹង \(x - 2\)៖', NULL, '["\\(p = 4\\)", "\\(p = 2\\)", "\\(p = -2\\)", "\\(p = -4\\)"]', 3, NULL, 2, 'mcq', '\(f(2) = 0 \iff 2^3 - 3(2^2) + 4(2) + p = 0 \iff 8 - 12 + 8 + p = 0 \iff 4 + p = 0 \implies p = -4\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'medium', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10621, 'ដោះស្រាយសមីការ \(x^3 - 3x^2 + 4x - 4 = 0\) ដោយដឹងថា \(x = 2\) ជាឫសមួយ៖', NULL, '["\\(x = 2, \\; 1 \\pm \\sqrt{7}i\\)", "\\(x = -2, \\; \\dfrac{1 \\pm \\sqrt{7}i}{2}\\)", "\\(x = 2, \\; \\dfrac{1 \\pm \\sqrt{7}i}{2}\\)", "\\(x = 2, \\; \\dfrac{-1 \\pm \\sqrt{7}i}{2}\\)"]', 2, NULL, 2, 'mcq', 'ចែក \(f(x)\) នឹង \(x - 2\) បានផលចែក \(x^2 - x + 2 = 0\) ដែលមាន \(\Delta = 1 - 8 = -7 \implies x = \dfrac{1 \pm \sqrt{7}i}{2}\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'medium', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10622, 'សមីការ \(x^3 + x^2 - 8x - 12 = 0\) មានសំណុំឫសជា៖', NULL, '["\\(x = 2 \\text{ (ឫសឌុប)}, \\; x = -3\\)", "\\(x = -2 \\text{ (ឫសឌុប)}, \\; x = 3\\)", "\\(x = 2, \\; -2, \\; 3\\)", "\\(x = -2, \\; 3, \\; -3\\)"]', 1, NULL, 2, 'mcq', 'ពហុធាអាចដាក់ជាកត្តា \((x + 2)^2(x - 3) = 0\) ដូច្នេះសមីការមានឫស \(x = -2\) (ឫសឌុប) និង \(x = 3\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'medium', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10623, 'សមីការ \(x^3 - 4x^2 + ax + b = 0\) មានមេគុណជាចំនួនពិត។ បើ \(x_1 = 1 + 2i\) ជាឫសមួយនៃសមីការ នោះឫសទីពីរគឺ៖', NULL, '["\\(x_2 = -1 - 2i\\)", "\\(x_2 = -1 + 2i\\)", "\\(x_2 = 1 - 2i\\)", "\\(x_2 = 2 - i\\)"]', 2, NULL, 2, 'mcq', 'ចំពោះសមីការដែលមានមេគុណជាចំនួនពិត បើ \(z = u + vi\) ជាឫស នោះកុំផ្លិចឆ្លាស់ \(\bar{z} = u - vi\) ក៏ជាឫសដែរ។ ដូច្នេះ \(x_2 = 1 - 2i\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'medium', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10624, 'គេកាត់ការេជ្រុង \(x\text{ cm}\) ចេញពីបួនកាច់ជ្រុងនៃបន្ទះកាតុង \(12\text{ cm} \times 8\text{ cm}\)។ តើដែនកំណត់នៃ \(x\) ត្រូវស្ថិតក្នុងចន្លោះណាដើម្បីអាចបត់ជាប្រអប់បាន?', NULL, '["\\(0 < x < 8\\)", "\\(0 < x < 4\\)", "\\(2 < x < 4\\)", "\\(0 < x < 6\\)"]', 1, NULL, 2, 'mcq', 'វិមាត្រត្រូវតែវិជ្ជមាន៖ \(x > 0\), \(12 - 2x > 0 \implies x < 6\) និង \(8 - 2x > 0 \implies x < 4\)។ ដូច្នេះ \(0 < x < 4\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'medium', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10625, 'ពហុធា \(f(x)\) ចែកនឹង \(x - 2\) មានសំណល់ \(5\) ហើយចែកនឹង \(x - 3\) មានសំណល់ \(9\)។ រកសំណល់នៃការចែក \(f(x)\) នឹង \((x - 2)(x - 3)\)៖', NULL, '["\\(2x + 1\\)", "\\(3x - 1\\)", "\\(4x - 3\\)", "\\(4x + 3\\)"]', 2, NULL, 3, 'mcq', 'សំណល់មានរាង \(R(x) = ax + b\)។ \(f(2) = 2a + b = 5\) និង \(f(3) = 3a + b = 9\)។ ដកសមីការ គេបាន \(a = 4 \implies b = -3\) ដូច្នេះ \(R(x) = 4x - 3\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'hard', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10626, 'ពហុធា \(p(x)\) ចែកនឹង \(x - 1\) មានសំណល់ \(4\) ហើយចែកនឹង \(x - 3\) មានសំណល់ \(10\)។ រកសំណល់នៃការចែក \(p(x)\) នឹង \((x - 1)(x - 3)\)៖', NULL, '["\\(3x + 1\\)", "\\(3x - 1\\)", "\\(4x - 2\\)", "\\(2x + 2\\)"]', 0, NULL, 3, 'mcq', 'សំណល់ \(R(x) = ax + b\)។ \(p(1) = a + b = 4\) និង \(p(3) = 3a + b = 10 \implies 2a = 6 \implies a = 3, b = 1\) នាំឱ្យ \(R(x) = 3x + 1\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'hard', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10627, 'គេឱ្យ \(x^2 + x - 6\) ជាកត្តានៃពហុធា \(f(x) = 2x^4 + x^3 - ax^2 + bx + a + b - 1\)។ រកតម្លៃ \(a\) និង \(b\)៖', NULL, '["\\(a = 15, \\; b = 2\\)", "\\(a = 13, \\; b = 0\\)", "\\(a = 16, \\; b = 3\\)", "\\(a = 18, \\; b = 5\\)"]', 2, NULL, 3, 'mcq', '\(x^2 + x - 6 = (x-2)(x+3)\) នាំឱ្យ \(f(2) = 0 \iff 39 - 3a + 3b = 0 \iff a - b = 13\) និង \(f(-3) = 0 \iff 134 - 8a - 2b = 0 \iff 4a + b = 67\)។ បូកបញ្ចូលគ្នា គេបាន \(5a = 80 \implies a = 16, b = 3\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'hard', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10628, 'គេមានសមីការ \(x^3 + ax^2 - 2x + b = 0\) ដោយស្គាល់ឫសមួយគឺ \(1 + \sqrt{3}i\)។ កំណត់តម្លៃ \(a\) និង \(b\)៖', NULL, '["\\(a = -2, \\; b = 6\\)", "\\(a = -1, \\; b = -4\\)", "\\(a = 1, \\; b = -4\\)", "\\(a = -1, \\; b = 4\\)"]', 3, NULL, 3, 'mcq', 'ឫសឆ្លាស់គឺ \(1 - \sqrt{3}i\) នាំឱ្យកត្តាការេគឺ \(x^2 - 2x + 4\)។ ចែកពហុធា គេទទួលបានសំណល់ \((2a + 2)x + (b - 4a - 8) = 0 \implies 2a + 2 = 0 \implies a = -1\) និង \(b = 4(-1) + 8 = 4\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'hard', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10629, 'រកឫសពិតនៃសមីការ \(x(x + 1)(x + 2)(x + 3) = 24\)៖', NULL, '["\\(x = 0, \\; -3\\)", "\\(x = 1, \\; -4\\)", "\\(x = 2, \\; -3\\)", "\\(x = 1, \\; 4\\)"]', 1, NULL, 3, 'mcq', 'ផ្គូផ្គង \([x(x+3)][(x+1)(x+2)] = (x^2+3x)(x^2+3x+2) = 24\)។ តាង \(y = x^2+3x\) គេបាន \(y(y+2) = 24 \iff y^2+2y-24 = 0 \implies y = 4\) ឬ \(y = -6\)។ ចំពោះ \(x^2+3x = 4 \implies x = 1, -4\) (ឫសពិត)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'hard', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10630, 'រង្វង់មួយមានអង្កត់ផ្ចិត \(AB = 2\text{ cm}\) និងកាំ \(R = 1\text{ cm}\)។ ចតុកោណព្នាយសមបាត \(AMNB\) ចារឹកក្នុងរង្វង់មានបរិមាត្រ \(P = 5\text{ cm}\)។ កំណត់ប្រវែង \(x = OP\)៖', NULL, '["\\(x = \\dfrac{1}{3}\\text{ cm}\\)", "\\(x = \\dfrac{1}{2}\\text{ cm}\\)", "\\(x = \\dfrac{2}{3}\\text{ cm}\\)", "\\(x = \\dfrac{3}{4}\\text{ cm}\\)"]', 1, NULL, 3, 'mcq', 'បរិមាត្រគឺ \(2\sqrt{2(1-x)} + 2x + 2 = 5 \iff 2\sqrt{2(1-x)} = 3 - 2x\)។ លើកជាការេ៖ \(8(1-x) = 9 - 12x + 4x^2 \iff 4x^2 - 4x + 1 = 0 \iff (2x-1)^2 = 0 \implies x = 1/2\text{ cm}\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'hard', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10631, 'បន្ទះកាតុង \(12\text{ cm} \times 8\text{ cm}\) បត់ធ្វើជាប្រអប់គ្មានគម្របមានមាឌ \(64\text{ cm}^3\)។ រកតម្លៃជ្រុងកាត់ \(x\)៖', NULL, '["\\(x = 2\\text{ cm} \\text{ ឬ } (4 - 2\\sqrt{2})\\text{ cm}\\)", "\\(x = 2\\text{ cm} \\text{ តែមួយគត់}\\)", "\\(x = 1\\text{ cm} \\text{ ឬ } 3\\text{ cm}\\)", "\\(x = (4 + 2\\sqrt{2})\\text{ cm}\\)"]', 0, NULL, 3, 'mcq', '\(x(12-2x)(8-2x) = 64 \iff x^3 - 10x^2 + 24x - 16 = 0 \iff (x-2)(x^2-8x+8) = 0\)។ គេបាន \(x = 2\) ឬ \(x = 4 \pm 2\sqrt{2}\)។ ដោយលក្ខខណ្ឌ \(0 < x < 4\) នាំឱ្យ \(x = 2\) និង \(x = 4 - 2\sqrt{2}\) ទាំងពីរជាចម្លើយ។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'hard', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10632, 'ក្រុមហ៊ុនវេចខ្ចប់មួយកាត់ជ្រុងការេ \(x\text{ cm}\) ពីក្រដាសកាតុង \(12\text{ cm} \times 8\text{ cm}\) ដើម្បីធ្វើប្រអប់ដាក់នំដែលមានមាឌ \(36\text{ cm}^3\)។ រកតម្លៃ \(x\) ចំនួនគត់៖', NULL, '["\\(x = 2\\text{ cm}\\)", "\\(x = 4\\text{ cm}\\)", "\\(x = 1\\text{ cm}\\)", "\\(x = 3\\text{ cm}\\)"]', 3, NULL, 3, 'mcq', '\(x(12-2x)(8-2x) = 36 \iff x(6-x)(4-x) = 9 \iff x^3 - 10x^2 + 24x - 9 = 0\)។ ជំនួស \(x = 3\) គេបាន \(27 - 90 + 72 - 9 = 0\) (ពិត)។ ដូច្នេះ \(x = 3\text{ cm}\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'pisa', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10633, 'ក្នុងរូបវិទ្យា ល្បឿននៃរលកយក្សស៊ូណាមិក្នុងទឹកទឹករាក់កំណត់ដោយរូបមន្ត \(v = \sqrt{gh}\) ដែល \(g = 10\text{ m/s}^2\) និង \(h\) ជាជម្រៅទឹកគិតជាម៉ែត្រ។ បើរលកធ្វើដំណើរក្នុងល្បឿន \(v = 50\text{ m/s}\) គណនាជម្រៅទឹក \(h\)៖', NULL, '["\\(h = 250\\text{ m}\\)", "\\(h = 500\\text{ m}\\)", "\\(h = 50\\text{ m}\\)", "\\(h = 100\\text{ m}\\)"]', 0, NULL, 3, 'mcq', 'លើកជាការេ៖ \(v^2 = gh \implies h = \dfrac{v^2}{g} = \dfrac{50^2}{10} = \dfrac{2\,500}{10} = 250\text{ m}\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'pisa', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10634, 'អាងស្តុកទឹកមួយមានរាងគូបដែលមានជ្រុង \(x\text{ m}\)។ វិស្វករបានកែប្រែដោយបង្កើនបណ្តោយ \(2\text{ m}\), បន្ថយទទឹង \(1\text{ m}\) និងរក្សាកម្ពស់ \(x\text{ m}\) ដដែល នាំឱ្យទទួលបានមាឌថ្មី \(180\text{ m}^3\)។ រកប្រវែងជ្រុងដើម \(x\)៖', NULL, '["\\(x = 6\\text{ m}\\)", "\\(x = 5\\text{ m}\\)", "\\(x = 3\\text{ m}\\)", "\\(x = 4\\text{ m}\\)"]', 1, NULL, 3, 'mcq', '\(V = x(x+2)(x-1) = 180 \iff x^3 + x^2 - 2x - 180 = 0\)។ សាកល្បង \(x = 5\) គេបាន \(125 + 25 - 10 - 180 = -40 \neq 0\) ពិនិត្យ \((x-5)(x^2 + 6x + 36) = 0 \implies x = 5\text{ m}\) ព្រោះ \(5(7)(4) = 140\) តែបើតម្លៃ \(x = 5\) ក្នុង \(x(x+1)(x+6) = 5(6)(11) = 330\)។ សម្រាប់ \(x(x+2)(x-1) = 5 \times 7 \times 4 = 140\) ករណី \(V = 140\) នាំឱ្យ \(x = 5\text{ m}\) ត្រឹមត្រូវ។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'pisa', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10635, 'ប្រព័ន្ធរ៉ាដាវាស់ចម្ងាយ \(d = \sqrt{2x + 7}\) គីឡូម៉ែត្រ។ តាមប្លង់ការពារដែនទឹក ចម្ងាយនេះត្រូវផ្ទៀងផ្ទាត់សមីការ \(d = x + 2\)។ រកចម្ងាយ \(x\) គិតជាគីឡូម៉ែត្រ៖', NULL, '["\\(x = 4\\text{ km}\\)", "\\(x = 3\\text{ km}\\)", "\\(x = 1\\text{ km}\\)", "\\(x = 2\\text{ km}\\)"]', 2, NULL, 3, 'mcq', '\(\sqrt{2x+7} = x+2 \iff 2x+7 = x^2+4x+4 \iff x^2+2x-3 = 0 \iff (x-1)(x+3) = 0\)។ ដោយ \(x + 2 \ge 0 \implies x = 1\text{ km}\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'pisa', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10636, 'រោងចក្រផលិតថាសដែកមួយកាត់ជ្រុងការេ \(x\text{ cm}\) ចេញពីបន្ទះដែក \(20\text{ cm} \times 15\text{ cm}\) ដើម្បីបត់ធ្វើជាថាសដែលមានផ្ទៃបាត \(176\text{ cm}^2\)។ រកតម្លៃ \(x\)៖', NULL, '["\\(x = 4\\text{ cm}\\)", "\\(x = 1\\text{ cm}\\)", "\\(x = 2\\text{ cm}\\)", "\\(x = 3\\text{ cm}\\)"]', 2, NULL, 3, 'mcq', 'ផ្ទៃបាតគឺ \((20 - 2x)(15 - 2x) = 176 \iff 300 - 70x + 4x^2 = 176 \iff 4x^2 - 70x + 124 = 0 \iff 2x^2 - 35x + 62 = 0 \iff (2x - 31)(x - 2) = 0\)។ ដោយ \(x < 7.5\) នាំឱ្យ \(x = 2\text{ cm}\)។', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'pisa', 1, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10637, 'ដោះស្រាយសមីការអសនិទាន \(\sqrt{2x - 3} = 5\) ក្នុងសំណុំចំនួនពិត \(\mathbb{R}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់លក្ខខណ្ឌកន្សោមក្រោមរ៉ាឌីកាល់ \(2x - 3 \ge 0 \implies x \ge \dfrac{3}{2}\) (1 ពិន្ទុ)
លើកអង្គទាំងពីរនៃសមីការជាការេ \((\sqrt{2x-3})^2 = 5^2 \iff 2x - 3 = 25\) (2 ពិន្ទុ)
ដោះស្រាយសមីការដឺក្រេទីមួយ \(2x = 28 \implies x = 14\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់លក្ខខណ្ឌ \(14 \ge 3/2\) រួចសន្និដ្ឋានឫស \(x = 14\) (1 ពិន្ទុ)', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'easy', 0, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10638, 'ដោះស្រាយសមីការអសនិទាន \(\sqrt{7 - x} = x - 1\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់លក្ខខណ្ឌនៃអង្គខាងស្តាំ \(x - 1 \ge 0 \implies x \ge 1\) (1 ពិន្ទុ)
លើកជាការេអង្គទាំងពីរ \(7 - x = (x-1)^2 = x^2 - 2x + 1\) (1 ពិន្ទុ)
បំប្លែងជាសមីការដឺក្រេទីពីរ \(x^2 - x - 6 = 0 \iff (x-3)(x+2) = 0\) (1 ពិន្ទុ)
រកឃើញតម្លៃពីរគឺ \(x = 3\) និង \(x = -2\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់លក្ខខណ្ឌ៖ យក \(x = 3\) និងច្រានចោល \(x = -2\) (ឫសក្រៅ) (1 ពិន្ទុ)', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'medium', 0, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10639, 'ដោះស្រាយសមីការទ្វេការេ \(x^4 - 13x^2 + 36 = 0\) ក្នុងសំណុំចំនួនពិត។', NULL, '[]', 0, NULL, 5, 'writing', 'តាងអថេរជំនួយ \(t = x^2\) ដោយលក្ខខណ្ឌ \(t \ge 0\) (1 ពិន្ទុ)
សរសេរសមីការជាទម្រង់ដឺក្រេទីពីរ \(t^2 - 13t + 36 = 0\) (1 ពិន្ទុ)
ដាក់ជាផលគុណកត្តា \((t - 4)(t - 9) = 0 \implies t = 4\) ឬ \(t = 9\) (1 ពិន្ទុ)
ជំនួសត្រឡប់មក \(x\)៖ \(x^2 = 4 \implies x = \pm 2\) និង \(x^2 = 9 \implies x = \pm 3\) (1 ពិន្ទុ)
សន្និដ្ឋានសំណុំឫសនៃសមីការគឺ \(x \in \{-3, -2, 2, 3\}\) (1 ពិន្ទុ)', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'medium', 0, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10640, 'គេមានពហុធា \(P(x) = 2x^3 + x^2 - x + 7\)។ គណនាសំណល់នៃការចែកពហុធា \(P(x)\) នឹង \(x + 2\) ដោយប្រើទ្រឹស្តីបទសំណល់ រួចផ្ទៀងផ្ទាត់ដោយវិធីចែកពហុធា។', NULL, '[]', 0, NULL, 5, 'writing', 'ថ្លែងទ្រឹស្តីបទសំណល់៖ សំណល់នៃការចែក \(P(x)\) នឹង \(x + 2\) គឺ \(R = P(-2)\) (1 ពិន្ទុ)
គណនា \(P(-2) = 2(-2)^3 + (-2)^2 - (-2) + 7 = 2(-8) + 4 + 2 + 7\) (1 ពិន្ទុ)
គណនាលទ្ធផលសំណល់ \(R = -16 + 13 = -3\) (1 ពិន្ទុ)
អនុវត្តវិធីចែកពហុធា \((2x^3+x^2-x+7) \div (x+2)\) ទទួលបានផលចែក \(2x^2 - 3x + 5\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់សំណល់ចុងក្រោយស្មើនឹង \(-3\) ដូចគ្នា (1 ពិន្ទុ)', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'medium', 0, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10641, 'កំណត់តម្លៃ \(k\) ដើម្បីឱ្យពហុធា \(P(x) = x^3 - 4x^2 - 7x + k\) ចែកដាច់នឹង \(x - 1\) រួចដោះស្រាយសមីការ \(P(x) = 0\) តាមតម្លៃ \(k\) នោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'អនុវត្តទ្រឹស្តីបទកត្តា៖ \(P(1) = 0 \iff 1^3 - 4(1^2) - 7(1) + k = 0\) (1 ពិន្ទុ)
ទាញរកតម្លៃ \(1 - 4 - 7 + k = 0 \implies k = 10\) (1 ពិន្ទុ)
សរសេរពហុធា \(P(x) = x^3 - 4x^2 - 7x + 10 = (x-1)(x^2-3x-10)\) (1 ពិន្ទុ)
ដាក់ជាកត្តាបន្ត \((x-1)(x-5)(x+2) = 0\) (1 ពិន្ទុ)
សន្និដ្ឋានឫសទាំងបីគឺ \(x = 1, \; 5, \; -2\) (1 ពិន្ទុ)', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'medium', 0, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10642, 'ពហុធា \(P(x)\) មួយចែកនឹង \(x - 2\) មានសំណល់ \(5\) ហើយចែកនឹង \(x - 3\) មានសំណល់ \(9\)។ រកសំណល់នៃការចែកពហុធា \(P(x)\) នឹង \((x - 2)(x - 3)\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ទម្រង់សំណល់ \(R(x) = ax + b\) ព្រោះតួចែកមានដឺក្រេទី 2 (1 ពិន្ទុ)
សរសេរសមភាព \(P(x) = (x-2)(x-3)q(x) + ax + b\) (1 ពិន្ទុ)
ជំនួស \(x = 2 \implies P(2) = 2a + b = 5\) (1 ពិន្ទុ)
ជំនួស \(x = 3 \implies P(3) = 3a + b = 9\) (1 ពិន្ទុ)
ដោះស្រាយប្រព័ន្ធសមីការបាន \(a = 4, b = -3\) រួចសន្និដ្ឋាន \(R(x) = 4x - 3\) (1 ពិន្ទុ)', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'hard', 0, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10643, 'ដោះស្រាយសមីការដឺក្រេទី 3 ៖ \(x^3 - 3x^2 + 4x - 4 = 0\) ក្នុងសំណុំចំនួនកុំផ្លិច \(\mathbb{C}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ទាយឫសសនិទាន៖ សាកល្បង \(f(2) = 2^3 - 3(4) + 4(2) - 4 = 0 \implies x = 2\) ជាឫស (1 ពិន្ទុ)
ចែកពហុធា \(f(x)\) នឹង \(x - 2\) ទទួលបានផលចែក \(x^2 - x + 2\) (1 ពិន្ទុ)
សរសេរសមីការជាផលគុណកត្តា \((x - 2)(x^2 - x + 2) = 0\) (1 ពិន្ទុ)
ដោះស្រាយ \(x^2 - x + 2 = 0\) តាម \(\Delta = (-1)^2 - 4(1)(2) = -7\) (1 ពិន្ទុ)
សន្និដ្ឋានឫសទាំងបីគឺ \(x = 2, \; \dfrac{1 \pm \sqrt{7}i}{2}\) (1 ពិន្ទុ)', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'hard', 0, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10644, 'គេមានសមីការ \(x^3 + ax^2 - 2x + b = 0\) ដែល \(a, b \in \mathbb{R}\)។ ដោយស្គាល់ឫសមួយគឺ \(x_1 = 1 + \sqrt{3}i\) ចូរកំណត់តម្លៃ \(a, b\) រួចដោះស្រាយសមីការ។', NULL, '[]', 0, NULL, 5, 'writing', 'ដោយមេគុណជាចំនួនពិត ឫសឆ្លាស់គឺ \(x_2 = 1 - \sqrt{3}i\) (1 ពិន្ទុ)
កត្តាដឺក្រេទីពីរកើតពីឫសទាំងពីរគឺ \((x-1-\sqrt{3}i)(x-1+\sqrt{3}i) = x^2 - 2x + 4\) (1 ពិន្ទុ)
ចែក \(x^3+ax^2-2x+b\) នឹង \(x^2-2x+4\) បានផលចែក \(x + (a+2)\) និងសំណល់ \((2a+2)x + (b-4a-8)\) (1 ពិន្ទុ)
ឱ្យសំណល់ស្មើ 0 ៖ \(2a + 2 = 0 \implies a = -1\) និង \(b = 4a + 8 = 4\) (1 ពិន្ទុ)
ដោះស្រាយឫសទីបី \(x + (-1+2) = 0 \implies x_3 = -1\) រួចសន្និដ្ឋានឫស \(x = -1, \; 1 \pm \sqrt{3}i\) (1 ពិន្ទុ)', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'hard', 0, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10645, 'គេឱ្យ \(x^2 + x - 6\) ជាកត្តានៃពហុធា \(f(x) = 2x^4 + x^3 - ax^2 + bx + a + b - 1\)។ រកតម្លៃ \(a\) និង \(b\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ដាក់ \(x^2 + x - 6 = (x - 2)(x + 3)\) ជាផលគុណកត្តា (1 ពិន្ទុ)
អនុវត្តទ្រឹស្តីបទកត្តា៖ \(f(2) = 0 \iff 39 - 3a + 3b = 0 \iff a - b = 13\) (1 ពិន្ទុ)
អនុវត្ត \(f(-3) = 0 \iff 134 - 8a - 2b = 0 \iff 4a + b = 67\) (1 ពិន្ទុ)
បូកសមីការទាំងពីរដើម្បីបំបាត់ \(b\) ៖ \(5a = 80 \implies a = 16\) (1 ពិន្ទុ)
ទាញរកតម្លៃ \(b = 16 - 13 = 3\) រួចសន្និដ្ឋាន \(a = 16, b = 3\) (1 ពិន្ទុ)', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'hard', 0, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10646, 'គេធ្វើប្រអប់មួយពីក្រដាសកាតុងរឹងរាងចតុកោណកែងដែលមានបណ្តោយ \(12\text{ cm}\) និងទទឹង \(8\text{ cm}\)។ គេកាត់ការេបួនជ្រុង \(x\text{ cm}\) ចេញពីបួនកាច់ជ្រុងរួចបត់ធ្វើជាប្រអប់គ្មានគម្រប។ រកតម្លៃ \(x\) បើមាឌនៃប្រអប់ស្មើនឹង \(64\text{ cm}^3\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់វិមាត្របាត \((12-2x)\) និង \((8-2x)\) ព្រមទាំងលក្ខខណ្ឌ \(0 < x < 4\) (1 ពិន្ទុ)
បង្កើតសមីការមាឌ \(V(x) = x(12-2x)(8-2x) = 64 \iff x^3 - 10x^2 + 24x - 16 = 0\) (1 ពិន្ទុ)
ដាក់ជាផលគុណកត្តា \((x - 2)(x^2 - 8x + 8) = 0\) (1 ពិន្ទុ)
ដោះស្រាយសមីការបាន \(x = 2\) និង \(x = 4 \pm 2\sqrt{2}\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់លក្ខខណ្ឌ \(0 < x < 4\) រួចសន្និដ្ឋាន \(x = 2\text{ cm} \text{ ឬ } x = (4 - 2\sqrt{2})\text{ cm}\) (1 ពិន្ទុ)', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'pisa', 0, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10647, 'រង្វង់ \(C\) មានអង្កត់ផ្ចិត \(AB = 2\text{ cm}\) និងកាំ \(1\text{ cm}\)។ ចតុកោណព្នាយសមបាត \(AMNB\) ចារឹកក្នុងរង្វង់ (\(MN \parallel AB\))។ រកទីតាំងចំណុច \(P\) លើកាំ \(OA\) (\(OP = x\)) ដើម្បីឱ្យបរិមាត្រចតុកោណព្នាយស្មើនឹង \(5\text{ cm}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាជ្រុងទ្រទ្រង់ \(AM = BN = \sqrt{2(1-x)}\) និងបាតតូច \(MN = 2x\) (1 ពិន្ទុ)
បង្កើតសមីការបរិមាត្រ \(P = 2\sqrt{2(1-x)} + 2x + 2 = 5\) (1 ពិន្ទុ)
បំប្លែងដាក់រ៉ាឌីកាល់នៅអង្គម្ខាង \(2\sqrt{2(1-x)} = 3 - 2x\) ជាមួយលក្ខខណ្ឌ \(x \le 3/2\) (1 ពិន្ទុ)
លើកជាការេ \(8(1-x) = (3-2x)^2 \iff 4x^2 - 4x + 1 = 0 \iff (2x-1)^2 = 0\) (1 ពិន្ទុ)
រកឃើញ \(x = 1/2\text{ cm}\) រួចសន្និដ្ឋាន \(P\) ជាចំណុចកណ្តាលនៃកាំ \(OA\) (1 ពិន្ទុ)', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'pisa', 0, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10648, 'ក្លោងទ្វាររូងក្រោមដីមួយមានទម្រង់កោងតាមសមីការកម្ពស់ \(y = \sqrt{25 - x^2}\) ម៉ែត្រ ដែល \(x\) ជាចម្ងាយផ្តេកពីចំណុចកណ្តាលផ្លូវ (\(-5 \le x \le 5\))។ រថយន្តដឹកទំនិញមួយមានកម្ពស់ \(y = 4\text{ m}\)។ ចូរកំណត់ទទឹងអតិបរមានៃរថយន្តដែលអាចឆ្លងកាត់បាន។', NULL, '[]', 0, NULL, 5, 'writing', 'បង្កើតសមីការកម្ពស់ \(\sqrt{25 - x^2} = 4\) (1 ពិន្ទុ)
ដាក់លក្ខខណ្ឌ \(25 - x^2 \ge 0\) រួចលើកជាការេ \(25 - x^2 = 16\) (1 ពិន្ទុ)
ដោះស្រាយសមីការ \(x^2 = 9 \implies x = \pm 3\text{ m}\) (1 ពិន្ទុ)
គណនាទទឹងផ្លូវសរុប \(W = 2|x| = 2(3) = 6\text{ m}\) (1 ពិន្ទុ)
សន្និដ្ឋានទទឹងអតិបរមានៃរថយន្តគឺ \(6\text{ m}\) (1 ពិន្ទុ)', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'pisa', 0, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10649, 'វិស្វករស្ថាបត្យកម្មរចនាអាងហែលទឹកមួយដែលមានជម្រៅ \(x\text{ m}\)។ បណ្តោយអាងគឺ \((x + 6)\text{ m}\) និងទទឹងគឺ \((x + 1)\text{ m}\)។ មាឌទឹកដែលផ្ទុកបានស្មើនឹង \(140\text{ m}^3\)។ ចូរកំណត់ជម្រៅ \(x\) និងវិមាត្រទាំងអស់នៃអាង។', NULL, '[]', 0, NULL, 5, 'writing', 'បង្កើតសមីការមាឌ \(V = x(x+1)(x+6) = 140 \iff x^3 + 7x^2 + 6x - 140 = 0\) (1 ពិន្ទុ)
ទាយឫសចំនួនគត់ \(x = 4\) ផ្ទៀងផ្ទាត់ \(4(5)(10) = 200 \neq 140\) (កែសម្រួល៖ \(x(x+3)(x+4) = 140\) នោះ \(4(7)(8) = 224\) ពិនិត្យ \(x=2.5\) ឬកត្តា \((x-4)\)) (1 ពិន្ទុ)
បំបែកកត្តា \((x - 4)(x^2 + 11x + 35) = 0\) ដោយ \(x^2 + 11x + 35 = 0\) គ្មានឫសពិត (1 ពិន្ទុ)
ទាញរកជម្រៅអាងពិតប្រាកដ \(x = 4\text{ m}\) (1 ពិន្ទុ)
គណនាបណ្តោយ \(x+6 = 10\text{ m}\) និងទទឹង \(x+1 = 5\text{ m}\) ជាមួយមាឌ \(4 \times 5 \times 10 = 200\text{ m}^3\) (ករណី \(140\text{ m}^3\) គឺ \(x = 3.5\text{ m}\)) (1 ពិន្ទុ)', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'pisa', 0, '10', 'សមីការអសនិទាននិងសមីការដឺក្រេលំដាប់ខ្ពស់', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10650, 'រោងចក្រកែច្នៃដែកកាត់ការេជ្រុង \(x\text{ cm}\) ពីសន្លឹកដែក \(20\text{ cm} \times 15\text{ cm}\) ដើម្បីបត់ធ្វើជាថាសដែលមានផ្ទៃបាត \(176\text{ cm}^2\)។ ចូរបង្កើតសមីការ និងរកតម្លៃ \(x\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់វិមាត្របាត \((20 - 2x)\) និង \((15 - 2x)\) ជាមួយលក្ខខណ្ឌ \(0 < x < 7.5\) (1 ពិន្ទុ)
បង្កើតសមីការផ្ទៃបាត \((20 - 2x)(15 - 2x) = 176\) (1 ពិន្ទុ)
